export default {
  props: ['isShow', 'tableIndex'],
  data: function data() {
    return {
      title: '照片上传',
      isUploading: false,
      baseImage: {
        index: null,
        imgData: null
      }
    };
  },
  computed: {
    isVisible: {
      get: function get() {
        return this.isShow;
      },
      set: function set(val) {
        this.$emit("update:isShow", val);
      }
    }
  },
  created: function created() {
    this.baseImage.index = this.tableIndex;
  },
  methods: {
    // 提交上传文件
    submitFileForm: function submitFileForm() {
      if (!this.baseImage.imgData) {
        this.$notify({
          title: '提示',
          message: '照片为空',
          type: 'warning'
        });
      } else {
        this.$emit('setVal', this.baseImage);
        this.isVisible = false;
      }
    },
    beforeUploadFile: function beforeUploadFile(file) {
      var _this = this;
      var isLimit = file.size / 1024;
      if (isLimit < 10) {
        this.$message.error('图片不能小于10KB');
        this.$refs.upload.clearFiles();
        return false;
      }
      if (isLimit > 50) {
        this.$message.error('图片不能大于50KB');
        this.$refs.upload.clearFiles();
        return false;
      }
      var reader = new FileReader();
      reader.readAsDataURL(file.raw);
      reader.onload = function (e) {
        // 此为base64编码
        _this.baseImage.imgData = e.target.result;
      };
      // 阻止默认上传行为
      return false;
    }
  }
};
